-- Clinical resource library (src/content/library), rendered at /resources/<slug>.
--
-- Adds the CBT/TCC and schema-therapy guides and worksheets, and turns the
-- one-line stub resources into full pages by pointing them at their library
-- entry. Stubs now covered by a fuller CBT guide are unpublished (not deleted).
INSERT INTO public.resources
  (slug, title, title_fr, title_ar, summary, summary_fr, summary_ar,
   format, category, topic_slug, content_url, read_minutes, is_published)
SELECT v.slug, v.title, v.title_fr, v.title_ar, v.summary, v.summary_fr, v.summary_ar,
       v.format, v.category, v.topic_slug, v.content_url, v.read_minutes, true
FROM (VALUES
  ('tcc-modele-cognitif', 'The cognitive model: situation, thought, emotion, behaviour', 'Le modèle cognitif : situation, pensée, émotion, comportement', 'النموذج المعرفي: الموقف والفكرة والانفعال والسلوك', 'The foundation of CBT: it is not the situation alone that shapes how we feel, but how we read it.', 'La base de la TCC : ce n''est pas la situation seule qui détermine ce que l''on ressent, mais la façon dont on l''interprète.', 'أساس العلاج المعرفي السلوكي: ليس الموقف وحده ما يحدد ما نشعر به، بل طريقة قراءتنا له.', 'guide', 'CBT', 'anxiety', '/resources/tcc-modele-cognitif', 6),
  ('tcc-tableau-des-pensees', 'Thought record (Beck''s 7 columns)', 'Tableau d''enregistrement des pensées (7 colonnes de Beck)', 'جدول تسجيل الأفكار (أعمدة بيك السبعة)', 'The core tool of cognitive restructuring: catch a painful thought, weigh the evidence, and find a more balanced one.', 'L''outil central de la restructuration cognitive : capturer une pensée douloureuse, examiner les preuves, et formuler une pensée plus équilibrée.', 'الأداة الأساسية لإعادة البناء المعرفي: التقاط فكرة مؤلمة، فحص الأدلة، وصياغة فكرة أكثر توازناً.', 'worksheet', 'CBT', 'anxiety', '/resources/tcc-tableau-des-pensees', 8),
  ('tcc-distorsions-cognitives', 'Cognitive distortions: 12 thinking traps', 'Les distorsions cognitives : 12 pièges de la pensée', 'التشوهات المعرفية: 12 فخاً في التفكير', 'Learn to recognise the most common reasoning errors so you can catch them in the moment.', 'Apprendre à reconnaître les erreurs de raisonnement les plus fréquentes pour les repérer sur le moment.', 'تعلّم التعرف على الأخطاء الأكثر شيوعاً في التفكير لتمسك بها في اللحظة.', 'guide', 'CBT', 'anxiety', '/resources/tcc-distorsions-cognitives', 7),
  ('tcc-questionnement-socratique', 'Socratic questioning: questions to test a thought', 'Le questionnement socratique : des questions pour tester une pensée', 'الحوار السقراطي: أسئلة لاختبار فكرة', 'A list of questions to examine an upsetting thought yourself, instead of taking it as fact.', 'Une liste de questions pour examiner vous-même une pensée dérangeante, au lieu de la prendre pour un fait.', 'قائمة أسئلة تساعدك على فحص فكرة مزعجة بنفسك، بدل قبولها كحقيقة.', 'worksheet', 'CBT', 'anxiety', '/resources/tcc-questionnement-socratique', 6),
  ('tcc-activation-comportementale', 'Behavioural activation: act first to get going again', 'L''activation comportementale : agir pour retrouver l''élan', 'التنشيط السلوكي: العودة إلى الحركة لاستعادة المزاج', 'In depression we wait to feel better before acting. Behavioural activation reverses the order.', 'Dans la dépression, on attend d''aller mieux pour agir. L''activation comportementale inverse l''ordre.', 'في الاكتئاب، ننتظر أن نشعر بتحسن لكي نتحرك. التنشيط السلوكي يعكس الترتيب.', 'worksheet', 'CBT', 'depression', '/resources/tcc-activation-comportementale', 8),
  ('tcc-hierarchie-exposition', 'Exposure hierarchy: facing fear step by step', 'La hiérarchie d''exposition : affronter la peur pas à pas', 'سلّم التعرّض: مواجهة الخوف خطوة بخطوة', 'Avoidance feeds anxiety. Graded exposure teaches the brain that the situation is less dangerous than it looks.', 'L''évitement nourrit l''anxiété. L''exposition progressive apprend au cerveau que la situation est moins dangereuse qu''elle n''en a l''air.', 'التجنب يغذي القلق. التعرّض المتدرج يعلّم الدماغ أن الموقف أقل خطراً مما يبدو.', 'worksheet', 'CBT', 'anxiety', '/resources/tcc-hierarchie-exposition', 8),
  ('tcc-resolution-de-problemes', 'Problem solving in 7 steps', 'La résolution de problèmes en 7 étapes', 'حل المشكلات في سبع خطوات', 'When worry is about a real problem, a structured method helps you move from rumination to action.', 'Quand l''inquiétude porte sur un vrai problème, une méthode structurée aide à passer de la rumination à l''action.', 'عندما يكون القلق مرتبطاً بمشكلة حقيقية، تساعد طريقة منظمة على الانتقال من الدوران في الحلقة إلى الفعل.', 'worksheet', 'CBT', 'stress', '/resources/tcc-resolution-de-problemes', 6),
  ('tcc-experiences-comportementales', 'Behavioural experiments: test a prediction for real', 'Les expériences comportementales : tester une prédiction en vrai', 'التجارب السلوكية: اختبار توقع في الواقع', 'The most powerful way to change a belief is to test it. Design a small experiment and compare your prediction with what happens.', 'La façon la plus puissante de changer une croyance, c''est de la mettre à l''épreuve. Concevez une petite expérience et comparez la prédiction à ce qui arrive.', 'أقوى طريقة لتغيير اعتقاد هي اختباره. صمّم تجربة صغيرة وقارن التوقع بما يحدث فعلاً.', 'worksheet', 'CBT', 'anxiety', '/resources/tcc-experiences-comportementales', 6),
  ('tcc-gerer-les-inquietudes', 'Managing worry: worry time and the decision tree', 'Gérer les inquiétudes : le temps d''inquiétude et l''arbre de décision', 'إدارة القلق: وقت مخصص للقلق وشجرة القرار', 'Two well-supported techniques to contain excessive worry: confine it to a set time, and separate what you can act on from what you can''t.', 'Deux techniques validées pour contenir l''inquiétude excessive : la circonscrire dans un temps dédié, et distinguer ce sur quoi l''on peut agir.', 'تقنيتان مثبتتان لاحتواء القلق المفرط: حصره في وقت محدد، والتمييز بين ما يمكن فعله وما لا يمكن.', 'worksheet', 'CBT', 'anxiety', '/resources/tcc-gerer-les-inquietudes', 7),
  ('tcc-sommeil-tcc-i', 'Principles of CBT for insomnia (CBT-I)', 'Les principes de la TCC de l''insomnie (TCC-I)', 'مبادئ العلاج المعرفي السلوكي للأرق', 'The first-line treatment recommended for chronic insomnia: re-link the bed with sleep and steady your rhythm.', 'Le traitement de première intention recommandé pour l''insomnie chronique : réassocier le lit au sommeil et stabiliser le rythme.', 'العلاج الأول الموصى به للأرق المزمن: إعادة ربط السرير بالنوم وتنظيم الإيقاع.', 'guide', 'CBT', 'stress', '/resources/tcc-sommeil-tcc-i', 8),
  ('schemas-besoins-et-18-schemas', 'Schema therapy: core needs and the 18 schemas', 'Thérapie des schémas : les besoins fondamentaux et les 18 schémas', 'العلاج بالمخططات: الحاجات الأساسية والمخططات الثمانية عشر', 'Where do the patterns that keep repeating in our lives come from? An introduction to core emotional needs and early maladaptive schemas.', 'D''où viennent les scénarios qui se répètent dans nos vies ? Une introduction aux besoins affectifs de base et aux schémas précoces inadaptés.', 'من أين تأتي الأنماط التي تتكرر في حياتنا؟ مدخل إلى الحاجات العاطفية الأساسية والمخططات المبكرة غير المتكيفة.', 'guide', 'Schema therapy', 'depression', '/resources/schemas-besoins-et-18-schemas', 9),
  ('schemas-les-modes', 'Modes: the states that take over inside us', 'Les modes : les états qui prennent le relais en nous', 'الأنماط (Modes): الحالات العاطفية التي تتناوب علينا', 'The vulnerable child, the inner critic, the detached protector, the healthy adult: a map of what happens inside from one moment to the next.', 'L''enfant vulnérable, le parent critique, le protecteur détaché, l''adulte sain : une carte pour comprendre ce qui se passe en soi d''un moment à l''autre.', 'الطفل الهش، الناقد الداخلي، الحامي المنفصل، والراشد السليم: خريطة لفهم ما يحدث في الداخل لحظة بلحظة.', 'guide', 'Schema therapy', 'stress', '/resources/schemas-les-modes', 8),
  ('schemas-styles-adaptation', 'Surrender, avoidance, overcompensation: how we cope', 'Capitulation, évitement, surcompensation : nos façons de faire face', 'الاستسلام والتجنب والتعويض المفرط: كيف نتعامل مع مخططاتنا', 'Three strategies we use to avoid feeling a schema''s pain, all of which keep it alive in the long run.', 'Trois stratégies que l''on utilise pour ne pas ressentir la douleur d''un schéma, et qui l''entretiennent toutes à long terme.', 'ثلاث طرق نلجأ إليها لتفادي ألم المخطط، وكلها تُبقيه حياً على المدى البعيد.', 'guide', 'Schema therapy', 'stress', '/resources/schemas-styles-adaptation', 6),
  ('schemas-carte-memoire', 'The schema flashcard', 'La carte-mémoire de schéma (flashcard)', 'بطاقة المخطط: ورقة عمل لحظة التنشيط', 'A card written in a calm moment and read when the schema fires, to link the current emotion to its origin and choose a healthy behaviour.', 'Une carte que l''on rédige à froid et que l''on relit quand le schéma s''active, pour relier l''émotion du moment à son origine et choisir un comportement sain.', 'بطاقة تكتبها مسبقاً وتقرؤها حين يُنشَّط المخطط، لتربط الانفعال الحالي بجذوره وتختار سلوكاً صحياً.', 'worksheet', 'Schema therapy', 'anxiety', '/resources/schemas-carte-memoire', 5),
  ('schemas-journal-des-modes', 'The mode diary', 'Le journal des modes', 'مفكرة الأنماط: تتبع الحالات خلال الأسبوع', 'A sheet to spot, over the week, which modes are triggered, what the vulnerable child needed and what the healthy adult would have done.', 'Une fiche pour repérer, au fil de la semaine, quels modes s''activent, de quoi l''enfant vulnérable avait besoin et ce que l''adulte sain aurait fait.', 'ورقة عمل لرصد الأنماط التي تنشط في المواقف اليومية، وما يحتاجه الطفل الهش، وما كان سيقوله الراشد السليم.', 'worksheet', 'Schema therapy', 'stress', '/resources/schemas-journal-des-modes', 5),
  ('schemas-techniques-experientielles', 'Experiential techniques: imagery and chair work', 'Les techniques expérientielles : imagerie et travail sur chaises', 'التقنيات التجريبية: إعادة كتابة الصور الذهنية وحوار الكراسي', 'How schema therapy works at the emotional level, and why these techniques are practised with a trained therapist.', 'Comment la thérapie des schémas agit au niveau émotionnel, et pourquoi ces techniques se pratiquent avec un thérapeute formé.', 'كيف يعمل العلاج بالمخططات على المستوى العاطفي، ولماذا تُمارس هذه التقنيات مع معالج مدرَّب.', 'guide', 'Schema therapy', 'depression', '/resources/schemas-techniques-experientielles', 7),
  ('grounding-54321', '5-4-3-2-1 grounding', 'L''ancrage 5-4-3-2-1', 'تمرين التأريض 5-4-3-2-1', 'A simple sensory exercise to come back to the present moment when anxiety surges or during a panic attack.', 'Un exercice sensoriel simple pour revenir dans l''instant présent quand l''anxiété monte ou pendant une attaque de panique.', 'تمرين حسّي بسيط يعيدك إلى اللحظة الحاضرة عند القلق الشديد أو نوبة الهلع.', 'worksheet', 'Wellbeing', 'anxiety', '/resources/grounding-54321', 3),
  ('box-breathing', 'Box breathing in 60 seconds', 'La respiration carrée en 60 secondes', 'تنفس الصندوق في 60 ثانية', 'A steady breathing rhythm (4-4-4-4) to calm the body before or after a stressful moment.', 'Un rythme respiratoire régulier (4-4-4-4) pour calmer le corps avant ou après une situation stressante.', 'إيقاع تنفس منتظم (4-4-4-4) لتهدئة الجسم قبل موقف ضاغط أو بعده.', 'guide', 'Wellbeing', 'stress', '/resources/box-breathing', 3),
  ('cognitive-defusion', 'Defusing from anxious thoughts', 'Se détacher des pensées anxieuses (défusion)', 'فك الالتحام مع الأفكار القلقة', 'From Acceptance and Commitment Therapy (ACT): seeing thoughts as thoughts, not as facts or orders.', 'Issue de la thérapie d''acceptation et d''engagement (ACT) : voir ses pensées comme des pensées, et non comme des faits ou des ordres.', 'من العلاج بالقبول والالتزام: أن ترى أفكارك كأفكار، لا كحقائق أو أوامر.', 'guide', 'ACT', 'anxiety', '/resources/cognitive-defusion', 5),
  ('values-compass', 'My values compass', 'Ma boussole de valeurs', 'بوصلة القيم', 'Clarify what truly matters to you in each area of life, and choose one small step in that direction this week.', 'Clarifier ce qui compte vraiment pour vous dans chaque domaine de vie, et choisir un petit pas dans cette direction cette semaine.', 'حدّد ما يهمك حقاً في مجالات حياتك، واختر خطوة صغيرة في اتجاهه هذا الأسبوع.', 'worksheet', 'ACT', 'self-esteem', '/resources/values-compass', 6),
  ('self-compassion-break', 'The 3-step self-compassion break', 'La pause d''auto-compassion en 3 étapes', 'استراحة التعاطف مع الذات في 3 خطوات', 'A brief way to meet a hard moment with kindness instead of harsh self-criticism.', 'Une façon brève de répondre à un moment difficile avec bienveillance plutôt qu''avec une autocritique sévère.', 'طريقة قصيرة للرد على لحظة صعبة بلطف بدل النقد الذاتي القاسي.', 'guide', 'Self-compassion', 'self-esteem', '/resources/self-compassion-break', 4),
  ('dear-man-script', 'DEAR MAN: asking for what you need', 'DEAR MAN : demander ce dont on a besoin', 'DEAR MAN: كيف تطلب ما تحتاجه', 'A Dialectical Behaviour Therapy (DBT) skill for making a clear request or a respectful refusal, without aggression.', 'Une compétence de la thérapie comportementale dialectique (TCD/DBT) pour formuler une demande claire ou un refus respectueux, sans agressivité.', 'مهارة من العلاج الجدلي السلوكي لصياغة طلب واضح أو رفض محترم دون عدوانية.', 'worksheet', 'DBT', 'relationships', '/resources/dear-man-script', 5),
  ('boundary-scripts', '5 boundary scripts', '5 phrases pour poser ses limites', 'خمس عبارات لوضع الحدود', 'Ready-made phrasings to say no, ask for time or stop a hurtful remark, while protecting the relationship.', 'Des formulations prêtes à l''emploi pour dire non, demander du temps ou arrêter une remarque blessante, tout en préservant la relation.', 'صيغ جاهزة لقول لا، طلب وقت، أو إيقاف كلام جارح، مع الحفاظ على العلاقة.', 'guide', 'DBT', 'relationships', '/resources/boundary-scripts', 5),
  ('i-statements', 'I-statements that land', 'Les messages « je » qui passent', 'عبارات "أنا" التي تصل', 'Voicing a complaint without the other person feeling attacked.', 'Exprimer un mécontentement sans que l''autre se sente attaqué.', 'كيف تعبّر عن انزعاجك دون أن يشعر الطرف الآخر بالهجوم.', 'guide', 'Wellbeing', 'relationships', '/resources/i-statements', 4),
  ('repair-after-conflict', 'Repairing after a fight', 'Réparer après une dispute', 'كيف تُصلح العلاقة بعد شجار', 'The steps after a conflict: calming down, understanding what each person went through, and reconnecting.', 'Les étapes après un conflit : se calmer, comprendre ce que chacun a vécu, et renouer le lien.', 'خطوات بعد الخلاف: التهدئة، فهم ما حدث لكل طرف، وإعادة التواصل.', 'guide', 'Wellbeing', 'relationships', '/resources/repair-after-conflict', 5),
  ('deep-work-blocks', 'Deep work blocks', 'Les blocs de travail profond', 'كتل العمل العميق', 'Setting aside focus time protected from interruptions, to lower stress and move forward on what matters.', 'Organiser des plages de concentration protégées des interruptions, pour réduire le stress et avancer sur ce qui compte.', 'تنظيم فترات تركيز محمية من المقاطعات لتقليل التوتر وإنجاز ما يهم.', 'guide', 'Wellbeing', 'workplace', '/resources/deep-work-blocks', 4),
  ('sport-mental-prep', 'Mental preparation for athletes: the basics', 'La préparation mentale du sportif : les bases', 'التحضير الذهني للرياضي: الأساسيات', 'Goals, self-talk, arousal control, imagery and routines: the five mental skills you train like the physical ones.', 'Objectifs, discours interne, gestion de l''activation, imagerie et routines : les cinq habiletés mentales qui se travaillent comme le physique.', 'الأهداف، الحوار الذاتي، التحكم في التنشيط، التخيل والروتين: المهارات الذهنية الخمس التي تُبنى بالتدريب.', 'guide', 'Sport', 'sport', '/resources/sport-mental-prep', 8),
  ('pre-performance-routine', 'The pre-performance routine', 'La routine de pré-performance', 'روتين ما قبل الأداء', 'Build a stable sequence of actions and thoughts before each key skill, to steady your attention.', 'Construire une séquence stable de gestes et de pensées avant chaque geste clé, pour stabiliser l''attention.', 'صمّم سلسلة ثابتة من الأفعال والأفكار قبل كل حركة حاسمة لتثبيت التركيز.', 'worksheet', 'Sport', 'sport', '/resources/pre-performance-routine', 5),
  ('visualization-script', 'Visualisation script for calm confidence', 'Script de visualisation pour un calme confiant', 'نص تخيّل للهدوء والثقة', 'Structured imagery using all the senses (the PETTLEP model) to prepare for a competition or a demanding situation.', 'Une imagerie structurée, avec tous les sens (modèle PETTLEP), pour se préparer à une compétition ou à une situation exigeante.', 'تخيّل منظم بكل الحواس (نموذج PETTLEP) للتحضير لمنافسة أو موقف صعب.', 'worksheet', 'Sport', 'sport', '/resources/visualization-script', 6),
  ('post-event-debrief', 'Post-event debrief in 4 questions', 'Le débrief d''après-événement en 4 questions', 'مراجعة ما بعد المنافسة في 4 أسئلة', 'A structured way to learn from every match, exam or presentation, without beating yourself up or ignoring mistakes.', 'Une façon structurée d''apprendre de chaque match, examen ou présentation, sans s''accabler ni ignorer les erreurs.', 'طريقة منظمة للتعلم من كل مباراة أو امتحان، دون جلد للذات ولا تجاهل للأخطاء.', 'worksheet', 'Sport', 'sport', '/resources/post-event-debrief', 4)
